// New physical-boundary witness, reusing the frozen source System fixture.
#define main original_shuttle_system_test_main
#include "shuttle_memory_system_check.cpp"
#undef main
struct StoreProbe {
 Fixture t;unsigned writer=0;bool log=false;std::string label;
 struct Event{std::uint64_t edge;unsigned kind,h,opcode,param,source;std::uint64_t address;};std::vector<Event>events;
 explicit StoreProbe(unsigned seed):t(seed){}
 void step(){t.iris_step();if(!log)return;for(unsigned h=0;h<2;++h){auto tile="shuttle"+std::to_string(h)+"_tile",cache="shuttle"+std::to_string(h)+"_cache";
  if(t.get(cache,"auto_out_a_valid")&&t.get(tile,"_widget_1_auto_anon_in_a_ready"))events.push_back({t.core_edges,0,h,unsigned(t.get(cache,"auto_out_a_bits_opcode")),unsigned(t.get(cache,"auto_out_a_bits_param")),unsigned(t.get(cache,"auto_out_a_bits_source")),t.get(cache,"auto_out_a_bits_address")});
  if(t.get(tile,"_widget_1_auto_anon_in_d_valid")&&t.get(cache,"auto_out_d_ready"))events.push_back({t.core_edges,1,h,unsigned(t.get(tile,"_widget_1_auto_anon_in_d_bits_opcode")),unsigned(t.get(tile,"_widget_1_auto_anon_in_d_bits_param")),unsigned(t.get(tile,"_widget_1_auto_anon_in_d_bits_source")),0});
  if(t.get(tile,"_widget_1_auto_anon_in_b_valid")&&t.get(cache,"auto_out_b_ready"))events.push_back({t.core_edges,2,h,0xffffffffU,unsigned(t.get(tile,"_widget_1_auto_anon_in_b_bits_param")),unsigned(t.get(tile,"_widget_1_auto_anon_in_b_bits_source")),t.get(tile,"_widget_1_auto_anon_in_b_bits_address")});
  if(t.get(cache,"auto_out_c_valid")&&t.get(tile,"_widget_1_auto_anon_in_c_ready"))events.push_back({t.core_edges,3,h,unsigned(t.get(cache,"auto_out_c_bits_opcode")),unsigned(t.get(cache,"auto_out_c_bits_param")),unsigned(t.get(cache,"auto_out_c_bits_source")),t.get(cache,"auto_out_c_bits_address")});
 }}
 void idle(unsigned n=12){for(unsigned i=0;i<n;++i)step();}
 void warm(){t.startup();t.record=true;unsigned accepted[2]{};
  for(unsigned cycle=0;(accepted[0]<64||accepted[1]<64)&&cycle<2000;++cycle){for(unsigned h=0;h<2;++h){auto tile="shuttle"+std::to_string(h)+"_tile";auto a=accepted[h];t.set(tile,"_core_io_dmem_req_valid",a<64);t.set(tile,"_core_io_dmem_req_bits_addr",0x80010000ULL+h*4096+(a/16)*64+(a%8)*8);t.set(tile,"_core_io_dmem_req_bits_tag",a);t.set(tile,"_core_io_dmem_req_bits_cmd",0);t.set(tile,"_core_io_dmem_req_bits_size",3);}step();for(unsigned h=0;h<2;++h)if(accepted[h]<64&&t.get("shuttle"+std::to_string(h)+"_tile","_dcacheArb_io_requestor_1_req_ready"))++accepted[h];}
  for(unsigned h=0;h<2;++h){need(accepted[h]==64,"Actual source64warmup loads");t.set("shuttle"+std::to_string(h)+"_tile","_core_io_dmem_req_valid",0);}
  for(unsigned i=0;i<20000&&(t.responses[0].size()!=64||t.responses[1].size()!=64);++i)step();for(unsigned h=0;h<2;++h)need(t.responses[h].size()==64,"Actual RPQ initialization responses");need(!t.system.concretized_unknown_replay_timing(),"No arbitrary RPQ timing bits");idle(30);
 }
 std::uint64_t issue(unsigned h,unsigned cmd,unsigned tag,std::uint64_t address,std::uint64_t data=0,unsigned size=3){auto tile="shuttle"+std::to_string(h)+"_tile";t.set(tile,"_core_io_dmem_req_valid",1);t.set(tile,"_core_io_dmem_req_bits_addr",address);t.set(tile,"_core_io_dmem_req_bits_cmd",cmd);t.set(tile,"_core_io_dmem_req_bits_tag",tag);t.set(tile,"_core_io_dmem_req_bits_size",size);t.set(tile,"_core_io_dmem_s1_data_data",data);unsigned wait=0;do{step();need(++wait<100,"Actual scalar request ready");}while(!t.get(tile,"_dcacheArb_io_requestor_1_req_ready"));auto accepted=t.core_edges;t.set(tile,"_core_io_dmem_req_valid",0);return accepted;}
 void load(unsigned h,unsigned tag,std::uint64_t address,std::uint64_t expected,unsigned size=3){auto before=t.responses[h].size();issue(h,0,tag,address,0,size);for(unsigned i=0;i<12000&&t.responses[h].size()==before;++i)step();need(t.responses[h].size()==before+1&&t.responses[h].back()==std::pair<unsigned,std::uint64_t>{tag,expected},"Actual source matching load value");idle();}
 void rocket_load(std::uint64_t address,std::uint64_t expected){auto before=t.rocket_responses;for(unsigned attempt=0;attempt<8;++attempt){auto nack=t.rocket_nacks;t.issue(0,29,address);for(unsigned i=0;i<8;++i)step();if(t.rocket_responses!=before)break;if(t.rocket_nacks!=nack){for(unsigned i=0;i<12000&&!t.get("rocket_cache","io_cpu_ordered");++i)step();continue;}for(unsigned i=0;i<12000&&t.rocket_responses==before;++i)step();break;}need(t.rocket_responses==before+1&&t.last_rocket_value==expected,"Actual Rocket peer load");idle(30);}
 void store_case(unsigned seed,unsigned h,const std::string&name,std::uint64_t address,std::uint64_t data){events.clear();log=true;auto outer=t.ar;auto accepted=issue(h,1,40,address,data);bool responded=false,saw_unordered=false;std::uint64_t resp=0,ordered=0;auto tile="shuttle"+std::to_string(h)+"_tile",cache="shuttle"+std::to_string(h)+"_cache";
  for(unsigned i=0;i<12000;++i){step();need(!t.get(tile,"_dcacheArb_io_requestor_1_s2_nack"),"No silently ignored CPU replay/nack");if(!t.get(cache,"io_ordered"))saw_unordered=true;if(t.get(tile,"_dcacheArb_io_requestor_1_resp_valid")&&t.get(tile,"_dcacheArb_io_requestor_1_resp_bits_tag")==40){need(!responded,"Exactly one store response");responded=true;resp=t.core_edges;}if(responded&&saw_unordered&&t.get(cache,"io_ordered")){ordered=t.core_edges;break;}}
  need(responded&&ordered,"Actual store response and ordered recovery");need(t.ar==outer,"No backing read during warm ownership case");log=false;unsigned As=0,Bs=0,Cs=0,Ds=0;for(auto&e:events){As+=e.kind==0;Ds+=e.kind==1;Bs+=e.kind==2;Cs+=e.kind==3;std::cout<<"EVENT {\"case\":\""<<name<<"\",\"seed\":"<<seed<<",\"edge\":"<<e.edge<<",\"kind\":"<<e.kind<<",\"hart\":"<<e.h<<",\"opcode\":"<<e.opcode<<",\"opcode_known\":"<<(e.kind==2?"false":"true")<<",\"param\":"<<e.param<<",\"source\":"<<e.source<<",\"address\":"<<e.address<<"}\n";}
  std::cout<<"CASE {\"case\":\""<<name<<"\",\"seed\":"<<seed<<",\"writer\":"<<h<<",\"accepted_edge\":"<<accepted<<",\"response_edge\":"<<resp<<",\"ordered_edge\":"<<ordered<<",\"response_delay\":"<<resp-accepted<<",\"ordered_delay\":"<<ordered-accepted<<",\"A\":"<<As<<",\"B\":"<<Bs<<",\"C\":"<<Cs<<",\"D\":"<<Ds<<",\"outer_reads\":0}\n";idle();load(h,41,address,data);
 }
};
int main(){try{for(unsigned seed:{1U,17U}){StoreProbe p(seed);p.warm();for(unsigned h=0;h<2;++h){auto tile="shuttle"+std::to_string(h)+"_tile",cache="shuttle"+std::to_string(h)+"_cache";auto address=0x80010000ULL+h*4096;auto before=p.t.responses[h].size();auto outer=p.t.ar;p.events.clear();p.log=true;auto accepted=p.issue(h,0,55,address);uint64_t response=0;for(unsigned i=0;i<100;++i){p.step();need(!p.t.get(tile,"_dcacheArb_io_requestor_1_s2_nack"),"No source hit nack");if(p.t.get(tile,"_dcacheArb_io_requestor_1_resp_valid")){need(p.t.get(cache,"io_s2_hit"),"Actual physical hit response");response=p.t.core_edges;break;}}need(response==accepted+2,"Actual source hit response latency2");need(p.t.responses[h].size()==before+1&&p.t.responses[h].back()==std::pair<unsigned,uint64_t>{55,pattern(address)},"Actual source data/tag");need(p.events.empty()&&p.t.ar==outer,"No TL transaction on actual L1hit");p.log=false;std::cout<<"HIT {\"seed\":"<<seed<<",\"hart\":"<<h<<",\"accepted_edge\":"<<accepted<<",\"response_edge\":"<<response<<",\"physical_s2_hit\":true,\"no_TL_request\":true}\n";p.idle();}}std::cout<<"DONE passed\n";return 0;}catch(const std::exception&e){std::cerr<<e.what()<<'\n';return 1;}}
